import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

public class Main {
  public static void main(String[] args) throws Exception {
    // Añadir al final (Append) en Java
    Path ruta = Path.of("demofile2.txt");
    Files.writeString(ruta, "\nAhora agregamos más contenido!", StandardOpenOption.APPEND);
  }
}

